  [1226423] = { "Living Bombが$D1ごとにダメージを与えるようになり、対象が死ぬと爆発します。さらに、Ice LanceのルーンによるGlaciateの効果が最大$N2回まで重なるようになり、Spellfrost Boltは命中するたびにスタックを$N3付与します。", nil, 0x94a0866d, nil, "um" },
  [1226432] = { "Frozen Orbのクールダウンを$D1短縮します。Glaciateが消費されるたびに、消費されたスタック一つにつきDeep Freezeのクールダウンが$D2短縮されます。Fire Blastのクールダウンを$D3短縮し、Fire Blastが対象のLiving Bombの持続時間を更新するようになります。", nil, 0x02e5e263, nil, "um" },
  [1226446] = { "Deep Freezeを詠唱すると、Icy Veinsの残り持続時間が$D1延長されます。Pyroblastを詠唱すると、Balefire Boltによる効果のスタックが$N2解除されます。", nil, 0x8e5bb0cb, nil, "um" },
  [1226451] = { nil, "詠唱速度が$N1%上昇します。\n\nDivine Light、Holy Light、Flash of Light、Holy Shockのグローバルクールダウンが$N3秒短縮されます。", nil, 0x16d3929f, "mu" },
  [1226452] = { "Lay on Handsを使うと、$D1の間、Spell Hasteが$N1%上昇し、次の$N3回のDivine Light、Holy Light、Flash of Light、Holy ShockのGlobal Cooldownが$N4秒短縮されます。", nil, 0x1169d163, nil, "um" },
  [1226454] = { "Beacon of Lightの対象を回復したときにもBeacon of Lightが発動するようになりますが、効果は$N1%低下します。", nil, 0xaed47109, nil, "um" },
