  [1226460] = { "両手武器を装備している間、Crusader StrikeとExorcismでHoly Powerを得て、与えるすべてのHolyダメージが$N1%増加します。最大$N2回まで重なります。", nil, 0xab6bcd9e, nil, "um" },
