  [1226961] = { "Lava Burst、Chain Lightning、Lightning Boltが、自分のFlame Shock Rank 5またはRank 6を受けている対象に命中すると、Flame Shockのダメージ1回分も与えます。", nil, 0xe3c1286e, nil, "um" },
  [1226977] = { "Overloadが発動する確率がさらに$N1%増加し、Lava Burstsのダメージが呪文のクリティカル率と同じ割合だけ増加します。Lightning BoltまたはChain Lightningがダメージを与えると、$D1以内に詠唱する次のLava Burstのダメージが$N3%増加します。最大$N4回まで重なります。", nil, 0x5e2b493a, nil, "um" },
  [1226978] = { "Chain Lightningがダメージを与えた対象が$N1体未満の場合、$N3体に足りない対象一体につきダメージが$N2%増加します。", nil, 0x850336b6, nil, "um" },
  [1226981] = { "自分または召喚した悪魔が与えるダメージに$N1%の確率で、$D1の間、もう一方の与えるダメージを$N2%増加させる効果が付きます。", nil, 0x3d3f4a2e, nil, "um" },
  [1226984] = { "Static Shockが有効な間、Lava Lash、Lava Burst、Stormstrikeに$N1%の確率で、Lightning Shieldにチャージを一つ追加する効果が付きます。チャージが$N2を超える場合、チャージを追加する代わりに、Lightning Shieldが即座に対象にダメージを与えます。", nil, 0x168b9084, nil, "um" },
  [1226986] = { "Fire Nova Totemのクールダウンを$N1%短縮し、ダメージを$N2%増加させ、マナコストを$N3%減少させます。さらに、Fire Nova Totemが設置と同時に即座に発動するようになります。", nil, 0x2812c13b, nil, "um" },
  [1226997] = { "Maelstrom Weaponが最大$N1チャージまで重なるようになります。両手武器を使っているときは、一度に$N2チャージを得ます。$N3チャージを超えて詠唱すると、超過したチャージ一つにつき、その呪文のダメージまたは回復量が$N4%増加します。$N5チャージの状態で詠唱すると、すべてのチャージを消費して二回詠唱します。", nil, 0xb75eaa2c, nil, "um" },
